CREATE TABLE "PushSubscription" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),"userId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE RESTRICT,"sessionId" uuid NOT NULL REFERENCES "Session"(id) ON DELETE CASCADE ON UPDATE RESTRICT,endpoint varchar(2048) NOT NULL UNIQUE,p256dh varchar(128) NOT NULL,auth varchar(32) NOT NULL,"createdAt" timestamptz(3) NOT NULL DEFAULT now());
CREATE INDEX "PushSubscription_userId_idx" ON "PushSubscription"("userId");CREATE INDEX "PushSubscription_sessionId_idx" ON "PushSubscription"("sessionId");
CREATE TABLE "PushDelivery" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),"notificationId" uuid NOT NULL REFERENCES "Notification"(id) ON DELETE CASCADE ON UPDATE RESTRICT,"subscriptionId" uuid NOT NULL REFERENCES "PushSubscription"(id) ON DELETE CASCADE ON UPDATE RESTRICT,state varchar(12) NOT NULL DEFAULT 'PENDING' CHECK(state IN('PENDING','ACCEPTED','CANCELLED','FAILED')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 8),"availableAt" timestamptz(3) NOT NULL DEFAULT now(),"leaseUntil" timestamptz(3),"providerStatus" integer,UNIQUE("notificationId","subscriptionId"));
CREATE INDEX "PushDelivery_state_availableAt_idx" ON "PushDelivery"(state,"availableAt");
ALTER TABLE "PushSubscription" ENABLE ROW LEVEL SECURITY;ALTER TABLE "PushDelivery" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON "PushSubscription","PushDelivery" FROM PUBLIC;
DO $$ DECLARE t text;BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='merkat_runtime') THEN FOREACH t IN ARRAY ARRAY['PushSubscription','PushDelivery'] LOOP EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO merkat_runtime',t);EXECUTE format('CREATE POLICY merkat_runtime ON %I TO merkat_runtime USING(true) WITH CHECK(true)',t);END LOOP;END IF;END $$;
